"use client";

import React from "react";

import { LightCrossIcon } from "../../lib/steez/icons/index";

import { useElementSize } from "../hooks/useElementSize";
import { LoadingProgressBar } from "./LoadingProgressBar";
import { useProgressBeep } from "./LoadingScreen.audio";
import { useFallingCrosses } from "./LoadingScreen.crosses";
import styles from "./LoadingScreen.module.css";

export interface LoadingScreenProps {
  progress: number;
  message?: string;
  logo?: React.ReactNode;
  title?: React.ReactNode;
  footerBrand?: React.ReactNode;
  audioFeedback?: boolean;
  fullscreen?: boolean;
  themeMode?: "auto" | "light" | "dark";
}

function resolveIsLightMode(themeMode: LoadingScreenProps["themeMode"]) {
  if (themeMode !== "auto") {
    return themeMode === "light";
  }

  if (typeof window === "undefined") {
    return false;
  }

  if (document.documentElement.getAttribute("data-theme") === "light") {
    return true;
  }

  try {
    return window.localStorage.getItem("theme") === "light";
  } catch {
    // Storage can be unavailable in privacy-restricted or sandboxed contexts.
    return false;
  }
}

/** Cycles 0–3 trailing dots every 400ms. */
function useEllipsis() {
  const [count, setCount] = React.useState(0);
  React.useEffect(() => {
    const interval = setInterval(() => setCount((current) => (current + 1) % 4), 400);
    return () => clearInterval(interval);
  }, []);
  return ".".repeat(count);
}

/** Follows `value` one short beat behind so the bar animates from its last value. */
function useDeferredProgress(value: number) {
  const [display, setDisplay] = React.useState(0);
  React.useEffect(() => {
    const timeout = setTimeout(() => setDisplay(value), 50);
    return () => clearTimeout(timeout);
  }, [value]);
  return display;
}

export function LoadingScreen({
  progress,
  message,
  logo,
  title = "LOADING",
  footerBrand,
  audioFeedback = false,
  fullscreen = true,
  themeMode = "auto",
}: LoadingScreenProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const bounds = useElementSize(containerRef);
  const hasWindow = typeof window !== "undefined";
  const screenWidth = bounds.width || (hasWindow ? window.innerWidth : 0);
  const screenHeight = bounds.height || (hasWindow ? window.innerHeight : 0);

  const crosses = useFallingCrosses(screenWidth);
  const displayProgress = useDeferredProgress(progress);
  const ellipsis = useEllipsis();
  useProgressBeep(audioFeedback, displayProgress);

  const cleanMessage = message ? message.replace(/\.+$/, "") : "";
  const isLightMode = resolveIsLightMode(themeMode);

  return (
    <div
      ref={containerRef}
      className={`${styles.screen} ${fullscreen ? styles.fullscreen : styles.contained} ${
        isLightMode ? styles.lightTheme : styles.darkTheme
      }`.trim()}
      style={
        {
          "--screen-height": `${screenHeight}px`,
          "--screen-width": `${screenWidth}px`,
        } as React.CSSProperties
      }
    >
      {crosses.map((cross) => (
        <div
          key={cross.id}
          className={styles.crossContainer}
          style={
            {
              "--cross-left": `${cross.x}px`,
              "--rotation": `${cross.rotation}deg`,
              "--ground": `${cross.groundOffset}%`,
              "--cross-scale": String(cross.scale),
              "--cross-opacity": String(cross.opacity),
            } as React.CSSProperties
          }
          onAnimationEnd={(event) => {
            if (event.animationName === "crossFall") {
              event.currentTarget.classList.add(styles.crossLanded);
            }
          }}
        >
          <div className={styles.crossSvg}>
            <LightCrossIcon className={styles.crossShape} />
          </div>
        </div>
      ))}

      <div className={styles.centerStack}>
        {logo ? <div className={styles.logoWrap}>{logo}</div> : null}
        <div className={styles.title}>{title}</div>
      </div>

      <LoadingProgressBar progress={displayProgress} className={styles.progressRow} />

      <div className={styles.footerStack}>
        {footerBrand ? (
          <div className={styles.footerBrand}>{footerBrand}</div>
        ) : null}
        <div className={styles.footerMessage}>
          {cleanMessage}
          {ellipsis}
        </div>
      </div>
    </div>
  );
}

.screen {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  overflow: hidden;
  font-family: var(--font-primary);
}

.fullscreen {
  position: fixed;
}

.contained {
  position: absolute;
  border: 1px solid var(--border-color);
}

.lightTheme {
  background: #fafbfc;
  color: #1a1a1a;
}

.darkTheme {
  background: #0a0a0a;
  color: #cbcbcc;
}

@keyframes crossFall {
  0% {
    transform: translateY(-450px) rotate(var(--rotation));
    opacity: 0;
  }

  10% {
    opacity: 1;
  }

  100% {
    transform: translateY(calc(var(--screen-height, 100vh) - var(--ground) - 50px))
      rotate(var(--rotation));
    opacity: 1;
  }
}

.crossContainer {
  position: absolute;
  top: 0;
  left: var(--cross-left, 0px);
  z-index: 1;
  will-change: transform;
  animation: crossFall 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

.crossSvg {
  transform: scale(var(--cross-scale, 1));
  transform-origin: center top;
  opacity: var(--cross-opacity, 0.6);
}

.crossLanded .crossSvg {
  opacity: 1 !important;
}

.crossShape {
  color: currentColor;
}

.centerStack {
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.logoWrap {
  display: flex;
  align-items: center;
  justify-content: center;
}

.title {
  font-size: clamp(24px, 8vw, 48px);
  font-weight: 700;
  letter-spacing: 8px;
}

.progressRow {
  position: relative;
  z-index: 10;
}

.footerStack {
  position: absolute;
  right: 40px;
  bottom: 40px;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.85rem;
}

.footerBrand {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

.footerMessage {
  opacity: 0.5;
  font-family: var(--font-mono);
  font-size: 14px;
}



@media (prefers-reduced-motion: reduce) {
  .crossContainer {
    animation: none !important;
    opacity: 1;
    transform: none;
  }
}

import React from "react";

import { LOADING_PROGRESS_SEGMENT_COUNT } from "./LoadingProgressBar";

type AudioWindow = Window & { webkitAudioContext?: typeof AudioContext };

function playBeep(ctx: AudioContext) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = "triangle";
  osc.frequency.value = 523.25;
  gain.gain.setValueAtTime(0.15, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + 0.08);
}

/**
 * When enabled, beeps each time `progress` (0–100) fills another progress-bar
 * segment. Audio unlocks on the first pointer or key press, as browsers require.
 */
export function useProgressBeep(enabled: boolean, progress: number) {
  const audioCtxRef = React.useRef<AudioContext | null>(null);
  const audioEnabledRef = React.useRef(false);
  const filledBarsRef = React.useRef(0);

  React.useEffect(() => {
    if (!enabled) return undefined;

    const enableAudio = async () => {
      const AudioContextClass =
        window.AudioContext || (window as AudioWindow).webkitAudioContext;
      if (!AudioContextClass) return;

      try {
        const ctx = audioCtxRef.current ?? new AudioContextClass();
        audioCtxRef.current = ctx;
        if (ctx.state === "suspended") {
          await ctx.resume();
        }
        audioEnabledRef.current = ctx.state === "running";
      } catch {
        audioEnabledRef.current = false;
      }
    };

    window.addEventListener("pointerdown", enableAudio, { once: true, passive: true });
    window.addEventListener("keydown", enableAudio, { once: true });

    return () => {
      window.removeEventListener("pointerdown", enableAudio);
      window.removeEventListener("keydown", enableAudio);
      if (audioCtxRef.current) {
        void audioCtxRef.current.close().catch(() => undefined);
        audioCtxRef.current = null;
      }
      audioEnabledRef.current = false;
    };
  }, [enabled]);

  React.useEffect(() => {
    if (!enabled) return;

    const filledBars = Math.round((progress / 100) * LOADING_PROGRESS_SEGMENT_COUNT);
    if (filledBars > filledBarsRef.current) {
      const ctx = audioCtxRef.current;
      if (ctx && audioEnabledRef.current) playBeep(ctx);
      filledBarsRef.current = filledBars;
    }
  }, [enabled, progress]);
}

import React from "react";

export interface Cross {
  id: number;
  x: number;
  rotation: number;
  scale: number;
  groundOffset: number;
  opacity: number;
}

/** Crosses kept on screen; older ones are dropped as new ones fall. */
export const MAX_CROSSES = 18;
const MIN_SURFACE_WIDTH = 160;

/** A cross with a random column, tilt, size, landing depth and opacity. */
export function makeCross(id: number, surfaceWidth: number, random: () => number): Cross {
  const width = Math.max(surfaceWidth, MIN_SURFACE_WIDTH);
  return {
    id,
    rotation: (random() - 0.5) * 6,
    x: random() * Math.max(width - 120, 24),
    scale: 0.4 + random() * 0.4,
    groundOffset: random() * 30,
    opacity: 0.4 + random() * 0.3,
  };
}

export function pushCross(crosses: readonly Cross[], next: Cross): Cross[] {
  return [...crosses.slice(-(MAX_CROSSES - 1)), next];
}

/** Drops a new cross every 400–700ms across a surface `width` pixels wide. */
export function useFallingCrosses(width: number): Cross[] {
  const [crosses, setCrosses] = React.useState<Cross[]>([]);
  const nextIdRef = React.useRef(0);

  React.useEffect(() => {
    if (typeof window === "undefined") return undefined;
    let timeoutId: ReturnType<typeof setTimeout> | undefined;

    const scheduleNextCross = () => {
      timeoutId = setTimeout(() => {
        nextIdRef.current += 1;
        const cross = makeCross(nextIdRef.current, width, Math.random);
        setCrosses((current) => pushCross(current, cross));
        scheduleNextCross();
      }, 400 + Math.random() * 300);
    };

    scheduleNextCross();
    return () => clearTimeout(timeoutId);
  }, [width]);

  return crosses;
}

import React from "react";

export type LoadingStage = "init" | "auth" | "agent" | "config" | "ready";

const STAGES: Record<LoadingStage, { progress: number; message: string }> = {
  init: { progress: 0, message: "Initializing..." },
  auth: { progress: 25, message: "Authenticating..." },
  agent: { progress: 50, message: "Loading agent..." },
  config: { progress: 75, message: "Loading configuration..." },
  ready: { progress: 100, message: "Preparing interface..." },
};

const EASE_STEPS = 20;
const EASE_STEP_MS = 100;

/**
 * Eases a progress value toward each loading stage's target over two seconds
 * and reports a message for the stage. Ending the load jumps to 100%.
 */
export function useLoadingProgress(
  isLoading: boolean,
  _phase?: string,
  stage: LoadingStage = "init",
) {
  const [progress, setProgress] = React.useState(0);
  const [message, setMessage] = React.useState(STAGES.init.message);
  const progressRef = React.useRef(0);

  const report = React.useCallback((value: number) => {
    progressRef.current = value;
    setProgress(value);
  }, []);

  React.useEffect(() => {
    if (!isLoading) {
      report(100);
      setMessage("Complete!");
      return undefined;
    }

    const target = STAGES[stage];
    setMessage(target.message);

    const start = progressRef.current;
    let step = 0;
    const interval = setInterval(() => {
      step += 1;
      report(Math.min(start + ((target.progress - start) * step) / EASE_STEPS, target.progress));
      if (step >= EASE_STEPS) {
        clearInterval(interval);
      }
    }, EASE_STEP_MS);

    return () => clearInterval(interval);
  }, [isLoading, report, stage]);

  return { progress, message };
}
